uint32_t rt_gl_function_count(void) {
    return (uint32_t)(sizeof(rt_gl_functions) / sizeof(rt_gl_functions[0]));
}

const rt_gl_function *rt_gl_function_at(uint32_t index) {
    return index < rt_gl_function_count() ? &rt_gl_functions[index] : NULL;
}

static float rt_gl_float(uint64_t slot) {
    uint32_t bits = (uint32_t)slot;
    float value;
    memcpy(&value, &bits, sizeof(value));
    return value;
}

